    @Test
    void insufficientStockIsConflictAndReservesNothing() throws Exception {
        long plenty = createProduct(1000, 10);
        long scarce = createProduct(1000, 1);
        placeOrder("u-" + uid(), "k-" + uid(), null, plenty, 5, scarce, 2)
